INSERT INTO workspace_adrs (adr_id, workspace_id, title, payload, router_time, time_basis, origin_installation, origin_machine, import_digest) VALUES (json_extract(?1, '$.record.envelope.id'), json_extract(?1, '$.record.workspace'), json_extract(?1, '$.record.title'), ?1, ?2, ?3, ?4, ?5, ?6) ON CONFLICT(adr_id) DO UPDATE SET workspace_id = excluded.workspace_id, title = excluded.title, payload = excluded.payload, router_time = excluded.router_time, time_basis = excluded.time_basis, origin_installation = excluded.origin_installation, origin_machine = excluded.origin_machine, import_digest = coalesce(workspace_adrs.import_digest, excluded.import_digest);
